import{_ as o,l as m,o as e,c as i,v as t,p as l,x as n,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"期权需求压力","description":"","frontmatter":{"title":"期权需求压力","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ni-option-demand-pressure.md","filePath":"quant/ni-option-demand-pressure.md","lastUpdated":1789023840000}'),h={name:"quant/ni-option-demand-pressure.md"};function d(A,a,u,B,P,_){const r=m("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="期权需求压力" tabindex="-1">期权需求压力 <a class="header-anchor" href="#期权需求压力" aria-label="Permalink to &quot;期权需求压力&quot;">​</a></h1><div class="epigraph"><p>做市商无法把期权完全对冲掉时，终端需求会把不可对冲残差的方差写进期权价格；一只合约上的买压，也会按不可对冲部分的协方差抬高其他合约。</p><footer>—— Gârleanu, Pedersen and Poteshman, Demand-Based Option Pricing, Review of Financial Studies, 2009；实证与对冲外溢见 Ni, Pearson and Poteshman 及相关后续</footer></div><p>教科书把期权价格写成标的过程的函数：给定波动、利率与分红，供需不出现。Ni、Pearson 与 Poteshman 这一支文献要补的，是中介资产负债表。终端投资者净买入看跌或看涨，期权做市商必须接下仓；只要复制有残差——随机波动、跳跃、离散对冲——仓位就有不可对冲风险，风险厌恶的中介会把价格抬离无摩擦公式。这就是<strong>需求压力</strong>（demand pressure）：它先改隐含波动曲面，再经 Delta 对冲改写标的路径。Bollen 与 Whaley（2004）已经看到带符号的期权成交与隐含波动同向变动；Gârleanu–Pedersen–Poteshman（2009）给出与不可对冲方差成比例的定价；Ni、Pearson、Poteshman 与 White（2021）把同一条仓位再写成对股票波动的非信息渠道。本篇写度量与机制，衔接<a href="/quant/vol-skew">波动偏斜</a>和<a href="/quant/greeks-hedge">Delta 对冲</a>，不讨论如何制造逼仓或绕开持仓限额。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无摩擦市场里，终端多头可以由做市商用标的完全复制，期权只是多余证券，需求不定价。现实里复制误差的方差 \\(\\mathrm{Var}(\\varepsilon)\\) 大于零。记终端对合约 \\(i\\) 的净需求为 \\(D_i\\)（以做市商空头为正），中介的风险厌恶为 \\(\\gamma\\)，则合约 \\(i\\) 相对无摩擦价格的加价近似</p> \\[\\Delta P_i \\;\\propto\\; \\gamma\\,\\mathrm{Var}(\\varepsilon_i)\\,D_i, \\]<p>交叉影响则换成 \\(\\mathrm{Cov}(\\varepsilon_i,\\varepsilon_j)D_j\\)。虚值指数看跌的不可对冲残差大，同一单位需求对价格的撬动也大——这与指数期权整体偏贵、个股期权相对便宜的截面事实同方向：终端在指数上净多期权（尤其是保护性看跌），在个股上净空。问题不是「有没有人在买期权」，而是做市商账上的净 Gamma、净 Vega 与不可对冲协方差，有没有大到足以移动隐含波动，并经对冲单移动现货。</p><p>第二条渠道是信息。Ni、Pan 与 Poteshman（2008）表明期权成交里有人在交易未来已实现波动；带方向的开仓也可以预测股票收益。需求压力论文要分开的是：<strong>非信息</strong>的存货渠道。Ni 等人（2021）的识别是做市商净 Gamma 与随后股票已实现波动负相关——正 Gamma 的再平衡是逆势的，负 Gamma 是顺势的——这与「知情交易把信息写入价格」不是同一回归。把两条渠道揉成「期权成交预测股票」，会把存货冲击当成 alpha。</p><h3 id="净需求必须按账户类型拆开" tabindex="-1">净需求必须按账户类型拆开 <a class="header-anchor" href="#净需求必须按账户类型拆开" aria-label="Permalink to &quot;净需求必须按账户类型拆开&quot;">​</a></h3><p>公开成交量是买卖配对后的总量，不含谁在开仓。Gârleanu 等人用交易所按账户类型划分的未平仓：公众客户、自营、做市商。终端净需求定义为非做市商的净多头。指数上客户长期净多看跌，个股上客户常净空（备兑、卖出波动），于是指数微笑更陡、个股更平。只看「看跌成交量升」而不看开平仓与账户类型，会把平仓与开仓、对冲与投机混成一个数字。</p><p><span class="marginnote">Ni、Pearson 与 Poteshman（2005）记录到期日股价钉在最大未平仓执行价附近。钉住是对冲流在 \\(K\\) 附近的机械结果，不是需求压力的全部；但它证明做市商的股票单足够大，能改变收盘分布。需求压力把同一机制从到期日推广到每个交易日的 Gamma 再平衡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量分三层，不要混用。第一层是带符号的期权成交：主动买入看涨减主动卖出看涨，看跌反向，再按 Delta 折成等价股票。Bollen–Whaley 用这一层解释隐含波动的日变化。第二层是未平仓的终端净头寸，对应 Gârleanu 等人的水平回归：贵的是「谁一直拿着」，不只是「今天谁在打」。第三层是做市商净 Gamma</p> \\[\\Gamma^{\\mathrm{MM}}_t=\\sum_{k} q^{\\mathrm{MM}}_{k,t}\\,\\Gamma_{k,t}, \\]<p>其中 \\(q^{\\mathrm{MM}}\\) 是做市商在系列 \\(k\\) 上的净仓（通常由成交容量代码累加）。\\(\\Gamma^{\\mathrm{MM}}\\gt 0\\) 时，标的上涨则 Delta 升，做市商卖标的；下跌则买。这是波动的减振器。符号反过来，再平衡放大波动。Ni 等人（2021）把这一层接到个股已实现波动与大变动概率上。</p><p>回归上应同时放需求与对冲。只回归隐含波动对期权成交，分不清信息与存货；只回归股票波动对 Gamma，又丢掉了曲面本身被买贵的那一段。完整的工作流是：用非做市商净需求解释隐含波动的水平与偏斜，用做市商 Gamma 解释随后的已实现波动，再检查两者是否被同一批开仓驱动。控制项包括已实现波动、跳、以及标的自身的买卖压力，避免把股票订单簿的冲击算到期权头上。</p><h3 id="不可对冲残差决定哪些合约更「贵」" tabindex="-1">不可对冲残差决定哪些合约更「贵」 <a class="header-anchor" href="#不可对冲残差决定哪些合约更「贵」" aria-label="Permalink to &quot;不可对冲残差决定哪些合约更「贵」&quot;">​</a></h3><p>完全可复制时 \\(\\mathrm{Var}(\\varepsilon)=0\\)，需求再大也不加价。残差来自随机波动、跳跃、离散再平衡与买卖价差。期限短、障碍近、虚值深的合约，残差方差更大，单位需求的价格影响也更大。这解释了为什么保护性虚值看跌的需求特别能陡化斜度，而平值短期限的需求更多表现为水平抬升。交叉项 \\(\\mathrm{Cov}(\\varepsilon_i,\\varepsilon_j)\\) 意味着买一只虚值看跌，也会抬高邻近执行价与邻近到期——做市商对冲的是一篮子不可对冲风险，不是单点。曲面因此以相关核的方式被需求「涂」过，而不是只在成交的那一个 \\(K\\) 上跳。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>终端买保护，做市商空头看跌：客户净多期权时，做市商净空期权，做市商 Gamma 为负、Delta 随现货下跌更负。指数保护的典型状态即是如此——现货跌则做市商必须再卖现货或期货，价格更跌。个股上客户常净空期权，做市商正 Gamma，再平衡是逆势的。同一套会计，在指数与个股上给出相反的波动反馈。需求压力首先定价的是期权；对冲是把那一页账翻译成标的订单流。</p><p>到期日是极限情形。剩余期限 \\(\\tau\\to 0\\) 时平值 Gamma 发散，Ni、Pearson 与 Poteshman（2005）的钉住是再平衡在执行价处变成「墙」。日常的需求压力是同一墙的矮版本：不必等到到期，只要净 Gamma 大、标的穿过密集开仓区，对冲单就会在短窗口里与价格同向或反向。Amaya 等人把这一机制做到 0DTE 指数期权，见<a href="/quant/amaya-0dte-volatility">0DTE 与波动</a>。</p><p><span class="marginnote">把「看跌成交量升」当成看空信号，忽略了开仓方向与谁在做市。客户买看跌是保护需求，做市商空头随后卖现货，短窗里像看空；客户卖看跌则相反。没有账户类型的成交量，符号不确定。</span></p><h3 id="与偏斜、风险溢价的分工" tabindex="-1">与偏斜、风险溢价的分工 <a class="header-anchor" href="#与偏斜、风险溢价的分工" aria-label="Permalink to &quot;与偏斜、风险溢价的分工&quot;">​</a></h3><p><a href="/quant/vol-skew">波动偏斜</a>可以来自崩盘恐惧、杠杆效应或需求。需求压力不否定前两者，它给出可检验的增量：在控制已实现偏度与杠杆之后，终端净需求仍解释隐含斜度的时变。风险溢价文献里的「保险很贵」，有一部分是中介风险厌恶乘上不可对冲方差，而不全是代表性投资者的边际效用。两者在指数看跌上经常同向，识别要靠账户持仓，而不是只靠斜率本身。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>美国的账户类型数据来自交易所的容量代码，延迟与覆盖都不是实时全市场。用公开的 option-to-stock 成交比或 Put/Call 比代替净需求，只能做粗筛选，不能声称复制了 Ni 或 Gârleanu 的回归。做市商内部还会把仓位转到其他柜台或用方差互换对冲 Vega，公开 Gamma 会低估真实存货。跳跃日线性对冲失效，需求压力的平方差公式在跳后要打折。</p><p>境内上市期权（沪深 50ETF、300ETF、中金所股指期权等）有交易所公布的做市商制度、持仓限额、限仓限报与投资者适当性。持仓限额把单一账户的 \\(D_i\\) 截断，不等于市场总存货消失，但会改变需求向哪些账户集中。不得把持仓限额、套保额度或做市豁免理解成可以拆分账户放大净需求；公开规则把限额写成约束，研究只估计约束内的价格影响。回测若假设无限卖出虚值看跌并不受限仓，与交易所规则冲突。</p><p><span class="marginnote">需求压力是中介定价，不是操纵指引。用大额期权去「制造」标的冲击，落入交易所有关异常交易与市场操纵的监控范围。本篇的工程含义是：风险系统要跟踪做市商一侧的净 Gamma，而不是设计如何把价格推过执行价。</span></p>',28)),(e(),l(E,null,{default:n(()=>[p(r,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E7%BB%88%E7%AB%AF%E5%87%80%E9%9C%80%E6%B1%82%20D%22%5D%20--%3E%20INV%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E5%AD%98%E8%B4%A7%22%5D%0A%20%20INV%20--%3E%20IV%5B%22%E4%B8%8D%E5%8F%AF%E5%AF%B9%E5%86%B2%E6%96%B9%E5%B7%AE%20%E2%86%92%20%E6%9C%9F%E6%9D%83%E5%8A%A0%E4%BB%B7%20%2F%20%E6%96%9C%E5%BA%A6%22%5D%0A%20%20INV%20--%3E%20G%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E5%87%80%20Gamma%22%5D%0A%20%20G%20--%3E%7C%22%E6%AD%A3%20Gamma%22%7C%20DAMP%5B%22%E9%80%86%E5%8A%BF%E5%86%8D%E5%B9%B3%E8%A1%A1%EF%BC%8C%E6%8A%91%E5%88%B6%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20G%20--%3E%7C%22%E8%B4%9F%20Gamma%22%7C%20AMP%5B%22%E9%A1%BA%E5%8A%BF%E5%86%8D%E5%B9%B3%E8%A1%A1%EF%BC%8C%E6%94%BE%E5%A4%A7%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20DAMP%20--%3E%20S%5B%22%E6%A0%87%E7%9A%84%20%2F%20%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20AMP%20--%3E%20S%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>期权不能被无残差复制时，终端净需求按不可对冲方差进入价格，并按协方差传到其他执行价与到期。</li><li>指数上客户净多保护、个股上常净空，对应指数期权更贵、斜度更陡的截面。</li><li>Ni–Pearson–Poteshman 把同一存货写成对标的的影响：到期钉住、日常 Gamma 再平衡与已实现波动。</li><li>度量要拆账户类型与开平仓；总量 Put/Call 不能代替净需求。</li><li>境内上市期权的持仓限额与做市规则是约束，不是可绕过的摩擦。</li><li>出处：Gârleanu, Pedersen &amp; Poteshman, <em>RFS</em>, 2009；Bollen &amp; Whaley, <em>Journal of Finance</em>, 2004；Ni, Pearson &amp; Poteshman, <em>JFE</em>, 2005；Ni, Pan &amp; Poteshman, <em>Journal of Finance</em>, 2008；Ni, Pearson, Poteshman &amp; White, <em>RFS</em>, 2021。</li></ul>',2))])}const G=o(h,[["render",d]]);export{D as __pageData,G as default};
